		}
	}
	if !inside(p.Path, sp.Path) {
		return Sprint{}, project.ProjectIndex{}, nil, fmt.Errorf("sprint path mismatch for %q", sp.Slug)
	}
	data, err := os.ReadFile(filepath.Join(p.Path, "project-index.md"))
